        for i in range(H):
            grid.append(data[index])
            index += 1

        row_ok = True
        for i in range(H):
            countA = 0
            for char in grid[i]:
                if char == 'A':
                    countA += 1
            if countA % 2 != 0:
                row_ok = False
                break
        if not row_ok:
            results.append("0")
            continue

        col_ok = True
        for j in range(W):
            countA = 0
            for i in range(H):
                if grid[i][j] == 'A':
                    countA += 1
            if countA % 2 != 0:
                col_ok = False
                break
        if not col_ok:
            results.append("0")
            continue

        base_row = [[0] * W for _ in range(H)]
        for i in range(H):
            current = 0
            for j in range(1, W):
                if grid[i][j-1] == 'A':
                    current = (current + 1) % 2
                base_row[i][j] = current

        base_col = [[0] * H for _ in range(W)]
        for j in range(W):
            current = 0
            for i in range(1, H):
                if grid[i-1][j] == 'A':
                    current = (current + 1) % 2
                base_col[j][i] = current

        total_nodes = H + W
        graph = [[] for _ in range(total_nodes)]

        for i in range(H):
            for j in range(W):
                if grid[i][j] == 'B':
                    c_val = (base_row[i][j] + base_col[j][i] + 1) % 2
                    u = i
                    v = H + j
                    graph[u].append((v, c_val))
                    graph[v].append((u, c_val))

        val = [-1] * total_nodes
        components = 0
        possible = True
        for i in range(total_nodes):
            if val[i] == -1:
                components += 1
                stack = [i]
                val[i] = 0
                while stack and possible:
                    u = stack.pop()
                    for v, w in graph[u]:
                        expected = (val[u] + w) % 2
                        if val[v] == -1:
                            val[v] = expected
                            stack.append(v)
                        else:
                            if val[v] != expected:
                                possible = False
                                break
            if not possible:
                break

        if not possible:
            results.append("0")
        else:
