class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        # dp[s] = [max_product_even, max_product_odd]
        # even: subsequence length is even, so next element (if added) will be at odd index (subtracted)
        # odd: subsequence length is odd, so next element (if added) will be at even index (added)
        dp = {}

        for x in nums:
            # We'll collect updates in a temporary dictionary to avoid using the same element multiple times in one pass
            updates = {}

            # For each existing state in dp
            for s, (even_prod, odd_prod) in dp.items():
                # If there is a subsequence with even length and sum s
                if even_prod != -1:
                    # Adding x: it will be at an odd index, so subtract x from the alternating sum
                    new_sum = s - x
                    new_prod = even_prod * x
                    if new_prod <= limit:
                        # This forms a subsequence of odd length
                        if new_sum not in updates:
                            updates[new_sum] = [-1, -1]
                        # Update the odd component
                        if new_prod > updates[new_sum][1]:
                            updates[new_sum][1] = new_prod

                # If there is a subsequence with odd length and sum s
                if odd_prod != -1:
                    # Adding x: it will be at an even index, so add x to the alternating sum
                    new_sum = s + x
                    new_prod = odd_prod * x
                    if new_prod <= limit:
                        # This forms a subsequence of even length
                        if new_sum not in updates:
                            updates[new_sum] = [-1, -1]
                        # Update the even component
                        if new_prod > updates[new_sum][0]:
                            updates[new_sum][0] = new_prod

            # Also, start a new subsequence with just x: length 1 (odd), sum = x, product = x
            if x <= limit:
                if x not in updates:
                    updates[x] = [-1, -1]
                # Update the odd component for sum x
                if x > updates[x][1]:
                    updates[x][1] = x

            # Merge updates into dp
            for s, (new_even, new_odd) in updates.items():
                if s not in dp:
                    dp[s] = [-1, -1]
                # Update even component
                if new_even != -1 and new_even > dp[s][0]:
                    dp[s][0] = new_even
                # Update odd component
                if new_odd != -1 and new_odd > dp[s][1]:
                    dp[s][1] = new_odd

        # Check for k
        if k in dp:
            res = -1
            if dp[k][0] != -1:
                res = max(res, dp[k][0])
            if dp[k][1] != -1:
                res = max(res, dp[k][1])
            return res
        return -1

class Solution:
    def minimumCost(self, nums: List[int], cost: List[int], k: int) -> int:
        n = len(nums)
        prefix_num = [0] * (n + 1)
        prefix_cost = [0] * (n + 1)
        for i in range(1, n + 1):
            prefix_num[i] = prefix_num[i-1] + nums[i-1]
            prefix_cost[i] = prefix_cost[i-1] + cost[i-1]

        dp = [float('inf')] * (n + 1)
        sub_count = [0] * (n + 1)
        dp[0] = 0

        for i in range(1, n + 1):
            for j in range(0, i):
                m = sub_count[j] + 1
                current_cost = dp[j] + (prefix_num[i] + k * m) * (prefix_cost[i] - prefix_cost[j])
                if current_cost < dp[i]:
                    dp[i] = current_cost
                    sub_count[i] = sub_count[j] + 1

        return dp[n]

class Solution:
    def minOperations(self, queries: List[List[int]]) -> int:
        powers = [1] * 17
        for i in range(1, 17):
            powers[i] = powers[i-1] * 4

        total_result = 0

        for l, r in queries:
            total_steps = 0
            for k in range(1, 17):
                low_bound = powers[k-1]
                high_bound = powers[k] - 1
                low = max(l, low_bound)
                high = min(r, high_bound)
                if low <= high:
                    count = high - low + 1
                    total_steps += count * k
            ops = (total_steps + 1) // 2
            total_result += ops

        return total_result

class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        return self.count(r) - self.count(l - 1)

    def count(self, n: int) -> int:
        if n == 0:
            return 0
        digits = list(map(int, str(n)))
        n_len = len(digits)
        total = 0
        max_sum = 9 * n_len
        for s in range(1, max_sum + 1):
            memo = {}
            def dp(pos, tight, started, current_sum, current_prod_mod):
                if current_sum > s:
                    return 0
                if pos == n_len:
                    if not started:
                        return 0
                    if current_sum == s and current_prod_mod == 0:
                        return 1
                    return 0

                state = (pos, tight, started, current_sum, current_prod_mod)
                if state in memo:
                    return memo[state]

                res = 0
                upper = digits[pos] if tight else 9
                for d in range(0, upper + 1):
                    new_tight = tight and (d == upper)
                    if not started and d == 0:
                        res += dp(pos + 1, new_tight, False, 0, 1)
                    elif not started and d > 0:
                        res += dp(pos + 1, new_tight, True, d, d % s)
                    else:
                        new_sum = current_sum + d
                        new_prod_mod = (current_prod_mod * d) % s
                        res += dp(pos + 1, new_tight, True, new_sum, new_prod_mod)

                memo[state] = res
                return res

            total += dp(0, True, False, 0, 1)
        return total

class TrieNode:
    __slots__ = 'count', 'children'
    def __init__(self):
        self.count = 0
        self.children = {}

class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        n = len(words)
        if n < k:
            return [0] * n
        if k > n - 1:
            return [0] * n

        root = TrieNode()
        word_paths = []

        for word in words:
            node = root
            path = [node]
            for char in word:
                if char not in node.children:
                    node.children[char] = TrieNode()
                node = node.children[char]
                path.append(node)
            word_paths.append(path)
            for node in path:
                node.count += 1

        ans = [0] * n

        for i in range(n):
            path = word_paths[i]
            for node in path:
                node.count -= 1

            best_depth = 0
            stack = [(root, 0)]
            while stack:
                node, depth = stack.pop()
                if node.count >= k:
                    if depth > best_depth:
                        best_depth = depth
                for child in node.children.values():
                    stack.append((child, depth + 1))

            ans[i] = best_depth

            for node in path:
                node.count += 1

        return ans

