    iterator = iter(data)
    try:
        N = int(next(iterator))
        K = int(next(iterator))
    except StopIteration:
        return

    # If K is 1, every vertex is a path of length 1, so it's always possible.
    if K == 1:
        print("Yes")
        return

    total_vertices = N * K
    adj = [[] for _ in range(total_vertices + 1)]

    for _ in range(total_vertices - 1):
        u = int(next(iterator))
        v = int(next(iterator))
        adj[u].append(v)
        adj[v].append(u)

    # DFS function
    # Returns:
    #   0 if the subtree is fully decomposed into complete paths
    #   a positive integer L (1 <= L < K) if there is an open path of length L ending at this node
    #   -1 if decomposition is impossible
    def dfs(u, p):
        open_children = []
        for v in adj[u]:
            if v == p:
                continue
            res = dfs(v, u)
            if res == -1:
                return -1
            if res != 0:
                open_children.append(res)

        # If more than one child has an open path, we can only extend one, the others would be incomplete.
        if len(open_children) > 1:
            return -1

        if len(open_children) == 1:
            L = open_children[0]
            new_len = L + 1
            if new_len == K:
                return 0
            elif new_len < K:
                return new_len
            else:
                # new_len > K, which should not happen if L < K
                return -1
        else:
            # No open paths from children, start a new path of length 1
            return 1

    result = dfs(1, -1)
    if result == 0:
        print("Yes")
    else:
        print("No")

