class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        INF = 10**18

        arr0 = [INF] * (n + 2)
        pairs_by_a = {}

        for pair in conflictingPairs:
            x, y = pair
            a = min(x, y)
            b = max(x, y)
            if a not in pairs_by_a:
                pairs_by_a[a] = []
            pairs_by_a[a].append(b)
            if b < arr0[a]:
                arr0[a] = b

        for a in pairs_by_a:
            pairs_by_a[a].sort()

        st = [[INF] * 20 for _ in range(n + 1)]
        for i in range(1, n + 1):
            st[i][0] = arr0[i]

        k = math.floor(math.log2(n)) if n > 0 else 0
        for j in range(1, k + 1):
            for i in range(1, n - (1 << j) + 2):
                st[i][j] = min(st[i][j-1], st[i + (1 << (j-1))][j-1])

        def rmq(l, r):
            if l > r:
                return INF
            j = math.floor(math.log2(r - l + 1))
            return min(st[l][j], st[r - (1 << j) + 1][j])

        R_old = [INF] * (n + 2)
        for i in range(n, 0, -1):
            R_old[i] = min(arr0[i], R_old[i+1])

        total = 0
        for i in range(1, n + 1):
            r = R_old[i]
            if r > i:
                end = min(n, r - 1)
                total += (end - i + 1)

        max_total = total

        for pair in conflictingPairs:
            x, y = pair
            a = min(x, y)
            b = max(x, y)

            if b != arr0[a]:
                new_total = total
            else:
                L = pairs_by_a[a]
                idx = bisect.bisect_left(L, b)
                if idx + 1 < len(L):
                    next_b = L[idx + 1]
                else:
                    next_b = INF

                C = R_old[a + 1]
                X = min(b, C)
                Y = min(next_b, C)

                if X == Y:
                    new_total = total
                else:
                    A = min(n, X - 1)
                    B = min(n, Y - 1)

                    low = 1
                    high = a
                    t = a + 1
                    while low <= high:
                        mid = (low + high) // 2
                        if mid > a - 1:
                            val = INF
                        else:
                            val = rmq(mid, a - 1)
                        if val > X:
                            t = mid
                            high = mid - 1
                        else:
                            low = mid + 1

                    delta = 0
                    if t <= a:
                        def compute_sum(t, end, C_val):
                            if t > C_val:
                                return 0
                            end_clamped = min(end, C_val)
                            if t > end_clamped:
                                return 0
                            count = end_clamped - t + 1
                            s = (C_val + 1) * count - (t + end_clamped) * count // 2
                            return s

                        sum_B = compute_sum(t, a, B)
                        sum_A = compute_sum(t, a, A)
                        delta = sum_B - sum_A
                    new_total = total + delta

            if new_total > max_total:
                max_total = new_total

        return max_total

class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)
        L = n + m - 1

        forced = [False] * L
        forced_char = [None] * L
        res = ['a'] * L

        for i in range(n):
            if str1[i] == 'T':
                for j in range(m):
                    pos = i + j
                    if forced[pos]:
                        if forced_char[pos] != str2[j]:
                            return ""
                    else:
                        forced[pos] = True
                        forced_char[pos] = str2[j]

        for k in range(L):
            if forced[k]:
                res[k] = forced_char[k]

        for i in range(n):
            if str1[i] == 'F':
                match = True
                for j in range(m):
                    if res[i + j] != str2[j]:
                        match = False
                        break
                if match:
                    found = False
                    for j in range(m - 1, -1, -1):
                        pos = i + j
                        if not forced[pos] and res[pos] != 'z':
                            res[pos] = chr(ord(res[pos]) + 1)
                            found = True
                            break
                    if not found:
                        return ""

        return "".join(res)

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        fact = [1] * 101
        for i in range(1, 101):
            fact[i] = fact[i-1] * i

        odd_count = (n + 1) // 2
        even_count = n // 2

        if n % 2 == 1:
            total = fact[odd_count] * fact[even_count]
        else:
            total = 2 * fact[odd_count] * fact[even_count]

        if k > total:
            return []

        if n % 2 == 1:
            start_parity = 'odd'
        else:
            block_size = fact[odd_count] * fact[even_count]
            if k <= block_size:
                start_parity = 'odd'
            else:
                start_parity = 'even'
                k -= block_size

        odds = [x for x in range(1, n+1) if x % 2 == 1]
        evens = [x for x in range(1, n+1) if x % 2 == 0]

        res = []
        for i in range(n):
            if start_parity == 'odd':
                if i % 2 == 0:
                    required = 'odd'
                else:
                    required = 'even'
            else:
                if i % 2 == 0:
                    required = 'even'
                else:
                    required = 'odd'

            if required == 'odd':
                candidates = odds[:]
            else:
                candidates = evens[:]

            found = False
            for cand in candidates:
                if required == 'odd':
                    rem_odds = len(odds) - 1
                    rem_evens = len(evens)
                else:
                    rem_odds = len(odds)
                    rem_evens = len(evens) - 1

                count = fact[rem_odds] * fact[rem_evens]
                if k <= count:
                    res.append(cand)
                    if required == 'odd':
                        odds.remove(cand)
                    else:
                        evens.remove(cand)
                    found = True
                    break
                else:
                    k -= count

            if not found:
                return []

        return res

