        children = []
        for v in graph[u]:
            if v == parent[u]:
                continue
            children.append(v)

        if not children:
            has_branch[u] = False
            has_g[u] = False
            continue

        vals = []
        for v in children:
            if has_branch[v]:
                vals.append(branch[v])
            else:
                vals.append(1)

