    def countSubstrings(self, s: str) -> int:
        n = len(s)
        ans = 0
        state = [None]
        for d in range(1, 10):
            state.append([0] * d)

        for c in s:
            digit = int(c)
            for d in range(1, 10):
                new_state = [0] * d
                for r in range(d):
                    if state[d][r] > 0:
                        new_r = (r * 10 + digit) % d
                        new_state[new_r] += state[d][r]
