class Solution:
    def minimumIncrements(self, nums: List[int], target: List[int]) -> int:
        k = len(target)
        total_masks = 1 << k

        lcm_table = [0] * total_masks
        for mask in range(1, total_masks):
            current_lcm = 1
            for i in range(k):
                if mask & (1 << i):
                    current_lcm = math.lcm(current_lcm, target[i])
            lcm_table[mask] = current_lcm

        min_cost = [float('inf')] * total_masks
        for mask in range(1, total_masks):
            lcm_val = lcm_table[mask]
            best = float('inf')
            for num in nums:
                cost = (lcm_val - num % lcm_val) % lcm_val
                if cost < best:
                    best = cost
            min_cost[mask] = best

        dp = [float('inf')] * total_masks
        dp[0] = 0

        for mask in range(1, total_masks):
            sub = mask
            while sub > 0:
                prev = mask ^ sub
                if dp[prev] != float('inf'):
                    new_cost = dp[prev] + min_cost[sub]
                    if new_cost < dp[mask]:
                        dp[mask] = new_cost
                sub = (sub - 1) & mask

        return dp[total_masks - 1]

