import sys

def mat_mul(A, B, mod):
    n = len(A)
    C = [[0] * n for _ in range(n)]
    for i in range(n):
        for k in range(n):
            if A[i][k] == 0:
                continue
            val_ik = A[i][k]
            for j in range(n):
                C[i][j] = (C[i][j] + val_ik * B[k][j]) % mod
    return C

def mat_pow(A, power, mod):
    n = len(A)
    # Identity matrix
    result = [[0] * n for _ in range(n)]
    for i in range(n):
        result[i][i] = 1

    base = A
    while power > 0:
        if power % 2 == 1:
            result = mat_mul(result, base, mod)
        base = mat_mul(base, base, mod)
        power //= 2
    return result

