class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        left = 0
        cost = 0
        ans = 0
        adj = []

        for right in range(n):
            if not adj:
                adj.append(nums[right])
            else:
                new_val = max(nums[right], adj[-1])
                cost += new_val - nums[right]
                adj.append(new_val)

            while cost > k and left <= right:
                adj.pop(0)
                left += 1
                cost = 0
                if left <= right:
                    prev = nums[left]
                    for i in range(left + 1, right + 1):
                        if nums[i] < prev:
                            cost += prev - nums[i]
                        else:
                            prev = nums[i]
            ans += (right - left + 1)

        return ans

import bisect

class Solution:
    def maximumWeight(self, intervals: List[List[int]]) -> List[int]:
        n = len(intervals)
        if n == 0:
            return []

        intervals_with_idx = []
        for i, (l, r, w) in enumerate(intervals):
            intervals_with_idx.append((l, r, w, i))

        sorted_intervals = sorted(intervals_with_idx, key=lambda x: (x[1], x[0], x[3]))
        end_times = [x[1] for x in sorted_intervals]

        dp = [[(-1, [])] * n for _ in range(5)]

        for i in range(n):
            dp[0][i] = (0, [])

        for k in range(1, 5):
            for i in range(n):
                start_i = sorted_intervals[i][0]
                pos = bisect.bisect_left(end_times, start_i)
                j = pos - 1

                opt1 = (-1, [])
                if i > 0:
                    opt1 = dp[k][i-1]

                opt2 = (-1, [])
                if j >= 0:
                    prev_weight, prev_indices = dp[k-1][j]
                    if prev_weight != -1:
                        new_indices = prev_indices + [sorted_intervals[i][3]]
                        opt2 = (prev_weight + sorted_intervals[i][2], new_indices)
                else:
                    if k == 1:
                        opt2 = (sorted_intervals[i][2], [sorted_intervals[i][3]])

                if opt1[0] == -1 and opt2[0] == -1:
                    dp[k][i] = (-1, [])
                elif opt1[0] == -1:
                    dp[k][i] = opt2
                elif opt2[0] == -1:
                    dp[k][i] = opt1
                else:
                    if opt1[0] > opt2[0]:
                        dp[k][i] = opt1
                    elif opt1[0] < opt2[0]:
                        dp[k][i] = opt2
                    else:
                        if opt1[1] < opt2[1]:
                            dp[k][i] = opt1
                        else:
                            dp[k][i] = opt2

        candidates = []
        for k in range(1, 5):
            w, indices = dp[k][n-1]
            if w != -1:
                candidates.append((w, indices))

        if not candidates:
            return []

        best = candidates[0]
        for i in range(1, len(candidates)):
            w1, idx1 = best
            w2, idx2 = candidates[i]
            if w2 > w1:
                best = candidates[i]
            elif w2 == w1:
                if idx2 < idx1:
                    best = candidates[i]

        return best[1]

class Solution:
    def makeStringGood(self, s: str) -> int:
        from collections import Counter
        cnt = Counter(s)
        n = len(s)
        ans = n
        for k in range(1, 27):
            for f in range(1, n // k + 2):
                total = k * f
                if total > n + 26:
                    continue
                for i in range(27 - k):
                    current = 0
                    for j in range(i, i + k):
                        current += abs(cnt[chr(ord('a') + j)] - f)
                    ans = min(ans, current)
        return ans

def build_cartesian_tree(A):
    n = len(A)
    left = [-1] * n
    right = [-1] * n
    stack = []
    for i in range(n):
        last = -1
        while stack and A[stack[-1]] < A[i]:
            last = stack.pop()
        if stack:
            right[stack[-1]] = i
        if last != -1:
            left[i] = last
        stack.append(i)
    return left, right

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        n = len(nums)
        # DSU initialization
        parent = list(range(n))
        rank = [0] * n

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]  # path compression
                x = parent[x]
            return x

        def union(x, y):
            rx, ry = find(x), find(y)
            if rx == ry:
                return
            # union by rank
            if rank[rx] < rank[ry]:
                parent[rx] = ry
            elif rank[rx] > rank[ry]:
                parent[ry] = rx
            else:
                parent[ry] = rx
                rank[rx] += 1

        # Map each number to its index
        num_to_index = {num: i for i, num in enumerate(nums)}

        # For each number, check its multiples
        for x in nums:
            # Start from 2*x, then 3*x, etc., as long as the multiple is <= threshold
            m = 2 * x
            while m <= threshold:
                if m in num_to_index:
                    # Union the current number x and the multiple m
                    idx_x = num_to_index[x]
                    idx_m = num_to_index[m]
                    union(idx_x, idx_m)
                m += x

        # Count the number of connected components: number of roots
        components = 0
        for i in range(n):
            if parent[i] == i:
                components += 1
        return components
